- name: Mint the pull-request app token
  if: ${{ steps.outcome.outputs.path == 'pr' }}
  id: app-token
  uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3.3.0
  with:
    app-id: ${{ vars.SEXTANT_APP_ID }}
    private-key: ${{ secrets.SEXTANT_APP_PRIVATE_KEY }}
    owner: seathatflowsinourveins
    repositories: sextant-next
    permission-contents: write
    permission-pull-requests: write

- name: Open or update the upkeep pull request
  id: cpr
  if: ${{ steps.outcome.outputs.path == 'pr' }}
  uses: peter-evans/create-pull-request@5f6978faf089d4d20b00c7766989d076bb2fc7f1 # v8.1.1
  with:
    token: ${{ steps.app-token.outputs.token }}
    branch: upkeep/${{ steps.brief.outputs.brief }}
    base: ${{ github.event.repository.default_branch }}
    title: 'upkeep: ${{ steps.brief.outputs.brief }}'
    body: ${{ steps.outcome.outputs.pr_body }}
    commit-message: 'upkeep: ${{ steps.brief.outputs.brief }}'
    delete-branch: true
